using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class PercyByssheShelley
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Dar'st thou amid the varied multitude To live alone, an isolated thing?", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Not the swart Pariah in some Indian grove, Lone, lean, and hunted by his brother's hate, Hath drunk so deep the cup of bitter fate As that poor wretch who cannot, cannot love: He bears a load which nothing can remove, A killing, withering weight.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Age cannot Love destroy, But perfidy can blast the flower, Even when in most unwary hour It blooms in Fancy's bower.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "I think that the leaf of a tree, the meanest insect on wh. we trample are in themselves arguments more conclusive than any which can be adduced that some vast intellect animates Infinity.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "The butchering of harmless animals cannot fail to produce much of that spirit of insane and hideous exultation in which news of a victory is related altho' purchased by the massacre of a hundred thousand men.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "It were much better that a sentient being should never have existed, than that it should have existed only to endure unmitigated misery.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Twilight, ascending slowly from the east, Entwined in duskier wreaths her braided locks O'er the fair front and radiant eyes of day, Night followed, clad with stars.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "The lone couch of his everlasting sleep.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Some say that gleams of a remoter world Visit the soul in sleep, — that death is slumber, And that its shapes the busy thoughts outnumber Of those who wake and live.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Sun-girt City, thou hast been Ocean's child, and then his queen; Now is come a darker day, And thou soon must be his prey.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Chameleons feed on light and air: Poets' food is love and fame.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Fame is love disguised.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "The seed ye sow another reaps; The wealth ye find another keeps; The robes ye weave another wears; The arms ye forge another bears.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Nothing in the world is single, All things by a law divine In one spirit meet and mingle — Why not I with thine?", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "The sunlight clasps the earth, And the moonbeams kiss the sea: What are all these kissings worth If thou kiss not me?", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "I arise from dreams of thee In the first sweet sleep of night, When the winds are breathing low, And the stars are shining bright.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "O lift me from the grass! I die! I faint! I fail! Let thy love in kisses rain On my lips and eyelids pale. My cheek is cold and white, alas! My heart beats loud and fast: O press it to thine own again, Where it will break at last!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Teas, Where small talk dies in agonies.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Peter was dull; he was at first Dull,—oh so dull, so very dull! Whether he talked, wrote, or rehearsed, Still with this dulness was he cursed! Dull,—beyond all conception, dull.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "I have drunken deep of joy, And I will taste no other wine tonight.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Good-night? ah! no; the hour is ill Which severs those it should unite; Let us remain together still, Then it will be good night.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "The breath Of accusation kills an innocent name, And leaves for lame acquittal the poor life, Which is a mask without it.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "An old, mad, blind, despised, and dying king, — Princes, the dregs of their dull race, who flow Through public scorn, — mud from a muddy spring, — Rulers who neither see, nor feel, nor know, But leech-like to their fainting country cling, Till they drop, blind in blood, without a blow.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "A lovely lady, garmented in light From her own beauty.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "First our pleasures die — and then Our hopes, and then our fears — and when These are dead, the debt is due, Dust claims dust — and we die too.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "His fine wit Makes such a wound, the knife is lost in it.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Though we eat little flesh and drink no wine, Yet let's be merry: we'll have tea and toast; Custards for supper, and an endless host Of syllabubs and jellies and mince-pies, And other such ladylike luxuries.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Rough wind, the moanest loud Grief too sad for song; Wild wind, when sullen cloud Knells all the night long; Sad storm, whose tears are vain, Bare woods, whose branches strain, Deep caves and dreary main, — Wail, for the world's wrong!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Music, when soft voices die, Vibrates in the memory — Odours, when sweet violets sicken, Live within the sense they quicken. Rose leaves, when the rose is dead, Are heaped for the beloved's bed; And so thy thoughts, when thou art gone, Love itself shall slumber on.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "One word is too often profaned For me to profane it; One feeling too falsely disdained For thee to disdain it.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "The desire of the moth for the star, Of the night for the morrow, The devotion to something afar From the sphere of our sorrow.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Swiftly walk over the western wave, Spirit of Night! Out of the misty eastern cave Where, all the long and lone daylight, Thou wovest dreams of joy and fear, Which make thee terrible and dear, — Swift be thy flight!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Death will come when thou art dead, Soon, too soon — Sleep will come when thou art fled; Of neither would I ask the boon I ask of thee, beloved Night — Swift be thine approaching flight, Come soon, soon!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "There is no sport in hate where all the rage Is on one side.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "When the lamp is shattered The light in the dust lies dead — When the cloud is scattered, The rainbow's glory is shed. When the lute is broken, Sweet tones are remembered not; When the lips have spoken, Loved accents are soon forgot.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Lift not the painted veil which those who live Call Life.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Art thou pale for weariness Of climbing heaven and gazing on the earth, Wandering companionless Among the stars that have a different birth', — And ever changing, like a joyless eye That finds no object worth its constancy?", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "That orbed maiden with white fire laden, Whom mortals call the moon.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Sing again, with your dear voice revealing A tone Of some world far from ours, Where music and moonlight and feeling Are one.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "You lie—under a mistake, For this is the most civil sort of lie That can be given to a man's face. I now Say what I think.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "There is no God! This negation must be understood solely to affect a creative Deity. The hypothesis of a pervading Spirit co-eternal with the universe remains unshaken.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "If he is infinitely good, what reason should we have to fear him? If he is infinitely wise, why should we have doubts concerning our future? If he knows all, why warn him of our needs and fatigue him with our prayers?", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "The body is placed under the earth, and after a certain period there remains no vestige even of its form. This is that contemplation of inexhaustible melancholy, whose shadow eclipses the brightness of the world.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "We must prove design before we can infer a designer.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Government has no rights; it is a delegation from several individuals for the purpose of securing their own. It is therefore just, only so far as it exists by their consent, useful only so far as it operates to their well-being.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "No man has a right to disturb the public peace, by personally resisting the execution of a law however bad. He ought to acquiesce, using at the same time the utmost powers of his reason, to promote its repeal.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Man has no right to kill his brother, it is no excuse that he does so in uniform. He only adds the infamy of servitude to the crime of murder.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Belief is involuntary; nothing involuntary is meritorious or reprehensible. A man ought not to be considered worse or better for his belief.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "A Christian, a Deist, a Turk, and a Jew, have equal rights: they are men and brethren.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "If a person's religious ideas correspond not with your own, love him nevertheless. How different would yours have been, had the chance of birth placed you in Tartary or India!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Titles are tinsel, power a corruptor, glory a bubble, and excessive wealth, a libel on its possessor.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "How wonderful is Death, Death and his brother Sleep!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "The king ... like the vulgar, thinks, feels, acts, and lives Just as his father did; the unconquered powers Of precedent and custom interpose Between a king and virtue.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Nature rejects the monarch, not the man; The subject, not the citizen; for kings And subjects, mutual foes, forever play A losing game into each other's hands, Whose stakes are vice and misery. The man Of virtuous soul commands not, nor obeys.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Power, like a desolating pestilence, Pollutes whate'er it touches; and obedience, Bane of all genius, virtue, freedom, truth, Makes slaves of men, and of the human frame A mechanized automaton.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Heaven's ebon vault, Studded with stars unutterably bright, Through which the moon's unclouded grandeur rolls, Seems like a canopy which love has spread To curtain her sleeping world.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "War is the statesman's game, the priest's delight, The lawyer's jest, the hired assassin's trade.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Thus suicidal selfishness, that blights The fairest feelings of the opening heart, Is destined to decay, whilst from the soil Shall spring all virtue, all delight, all love, And judgment cease to wage unnatural war With passion's unsubduable array.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Gold is a living god and rules in scorn, All earthly things but virtue.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "The word of God has fenced about all crimes with Holiness.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "And man ... no longer now He slays the lamb that looks him in the face, And horribly devours his mangled flesh.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "A husband and wife ought to continue so long united as they love each other. Any law which should bind them to cohabitation for one moment after the decay of their affection, would be a most intolerable tyranny, and the most unworthy of toleration.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Love is free: to promise for ever to love the same woman, is not less absurd than to promise to believe the same creed: such a vow in both cases, excludes us from all enquiry.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Chastity is a monkish and evangelical superstition, a greater foe to natural temperance even than unintellectual sensuality; it strikes at the root of all domestic happiness, and consigns more than half the human race to misery.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "By all that is sacred in our hopes for the human race, I conjure those who love happiness and truth, to give a fair trial to the vegetable system.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "It has been the persuasion of an immense majority of human beings in all ages and nations that we continue to live after death,—that apparent termination of all the functions of sensitive and intellectual existence.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Let us bring the question to the test of experience and fact; and ask ourselves, considering our nature in its entire extent, what light we derive from a sustained and comprehensive view of its component parts, which may enable us to assert with certainty that we do or do not live after death.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "If it be proved that the world is ruled by a Divine Power, no inference necessarily can be drawn from that circumstance in favour of a future state.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Nor, if a future state be clearly proved, does it follow that it will be a state of punishment or reward.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "He observes the mental powers increase and fade with those of the body, and even accommodate themselves to the most transitory changes of our physical nature.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Sleep suspends many of the faculties of the vital and intellectual principle; drunkenness and disease will either temporarily or permanently derange them.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Madness or idiotcy may utterly extinguish the most excellent and delicate of those powers.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "In old age the mind gradually withers; and as it grew and was strengthened with the body, so does it together with the body sink into decrepitude.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Assuredly these are convincing evidences that so soon as the organs of the body are subjected to the laws of inanimate matter, sensation, and perception, and apprehension are at an end.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "It is probable that what we call thought is not an actual being, but no more than the relation between certain parts of that infinitely varied mass, of which the rest of the universe is composed, and which ceases to exist as soon as those parts change their position with regard to each other.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Spirit of Beauty, that dost consecrate With thine own hues all thou dost shine upon Of human thought or form, where art thou gone? Why dost thou pass away and leave our state, This dim vast vale of tears, vacant and desolate?", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Ask why the sunlight not for ever Weaves rainbows o'er yon mountain-river, Why aught should fail and fade that once is shown, Why fear and dream and death and birth Cast on the daylight of this earth Such gloom, why man has such a scope For love and hate, despondency and hope?", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Thy light alone like mist o'er mountains driven, Or music by the night-wind sent Through strings of some still instrument, Or moonlight on a midnight stream, Gives grace and truth to life's unquiet dream.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Then black despair, The shadow of a starless night, was thrown Over the world in which I moved alone.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "A wild dissolving bliss Over my frame he breathed, approaching near, And bent his eyes of kindling tenderness Near mine, and on my lips impressed a lingering kiss.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Can man be free if woman be a slave?", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "With hue like that when some great painter dips His pencil in the gloom of earthquake and eclipse.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Fear not the future, weep not for the past.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "\"My name is Ozymandias, king of kings: Look on my works, ye mighty, and despair!\"", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Nothing beside remains: round the decay Of that colossal wreck, boundless and bare, The lone and level sands stretch far away.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "I love all waste And solitary places; where we taste The pleasure of believing what we see Is boundless, as we wish our souls to be.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "It is our will That thus enchains us to permitted ill. We might be otherwise, we might be all We dream of happy, high, majestical. Where is the love, beauty and truth we seek, But in our mind? and if we were not weak, Should we be less in deed than in desire?", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Those who inflict must suffer, for they see The work of their own hearts, and this must be Our chastisement or recompense.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Most wretched men Are cradled into poetry by wrong; They learn in suffering what they teach in song.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Wild Spirit, which art moving everywhere; Destroyer and preserver; hear, oh, hear!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Thou dirge Of the dying year, to which this closing night Will be the dome of a vast sepulchre, Vaulted with all thy congregated might.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Oh, lift me as a wave, a leaf, a cloud! I fall upon the thorns of life! I bleed!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Make me thy lyre, even as the forest is: What if my leaves are falling like its own? The tumult of thy mighty harmonies Will take from both a deep autumnal tone, Sweet though in sadness. Be thou, Spirit fierce, My spirit! Be thou me, impetuous one!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "I met Murder on the way — He had a mask like Castlereagh — Very smooth he looked, yet grim; Seven blood-hounds followed him.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "All were fat; and well they might Be in admirable plight, For one by one, and two by two, He tossed them human hearts to chew.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "And many more Destructions played In this ghastly masquerade, All disguised, even to the eyes, Like Bishops, lawyers, peers, or spies.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Last came Anarchy: he rode On a white horse, splashed with blood; He was pale even to the lips, Like Death in the Apocalypse.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "And with glorious triumph, they Rode through England proud and gay, Drunk as with intoxication Of the wine of desolation.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "My father Time is weak and gray With waiting for a better day; See how idiot-like he stands, Fumbling with his palsied hands!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "What is Freedom? — ye can tell That which slavery is, too well — For its very name has grown To an echo of your own.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Thou art Justice — ne'er for gold May thy righteous laws be sold As laws are in England — thou Shield'st alike the high and low.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "What if English toil and blood Was poured forth, even as a flood? It availed, Oh, Liberty, To dim, but not extinguish thee.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Spirit, Patience, Gentleness, All that can adorn and bless Art thou — let deeds, not words, express Thine exceeding loveliness.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Let the blue sky overhead, The green earth on which ye tread, All that must eternal be Witness the solemnity.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "From the haunts of daily life Where is waged the daily strife With common wants and common cares Which sows the human heart with tares.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Be your strong and simple words Keen to wound as sharpened swords, And wide as targes let them be, With their shade to cover ye.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Stand ye calm and resolute, Like a forest close and mute, With folded arms and looks which are Weapons of unvanquished war.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "The old laws of England — they Whose reverend heads with age are gray, Children of a wiser day; And whose solemn voice must be Thine own echo — Liberty!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Rise like Lions after slumber In unvanquishable number — Shake your chains to earth like dew Which in sleep had fallen on you — Ye are many — they are few.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Hail to thee, blithe Spirit! Bird thou never wert, That from Heaven, or near it, Pourest thy full heart In profuse strains of unpremeditated art.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Higher still and higher From the earth thou springest, Like a cloud of fire; The blue deep thou wingest, And singing still dost soar and soaring ever singest.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Like an unbodied joy whose race is just begun.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Thou art unseen, but yet I hear thy shrill delight.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "We look before and after, And pine for what is not: Our sincerest laughter With some pain is fraught; Our sweetest songs are those that tell of saddest thought.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "We are all Greeks. Our laws, our literature, our religion, our arts have their root in Greece.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Life may change, but it may fly not; Hope may vanish, but can die not; Truth be veiled, but still it burneth; Love repulsed, — but it returneth!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Kings are like stars — they rise and set, they have The worship of the world, but no repose.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "The moon of Mahomet Arose, and it shall set; While, blazoned as on heaven's immortal noon, The cross leads generations on.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Let there be light! said Liberty, And like sunrise from the sea, Athens arose!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "But Greece and her foundations are Built below the tide of war, Based on the crystalline sea Of thought and its eternity; Her citizens, imperial spirits, Rule the present from the past, On all this world of men inherits Their seal is set.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "The world's great age begins anew, The golden years return, The earth doth like a snake renew Her winter weeds outworn; Heaven smiles, and faiths and empires gleam, Like wrecks of a dissolving dream.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "The world is weary of the past, Oh, might it die or rest at last!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "True Love in this differs from gold and clay, That to divide is not to take away. Love is like understanding, that grows bright, Gazing on many truths; 'tis like thy light, Imagination!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Mind from its object differs most in this: Evil from good; misery from happiness; The baser from the nobler; the impure And frail, from what is clear and must endure.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "If you divide suffering and dross, you may Diminish till it is consumed away; If you divide pleasure and love and thought, Each part exceeds the whole; and we know not How much, while any yet remains unshared, Of pleasure may be gained, of sorrow spared:", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Love's very pain is sweet, But its reward is in the world divine Which, if not here, it builds beyond the grave.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "The cemetery is an open space among the ruins covered in winter with violets and daisies. It might make one in love with death, to think that one should be buried in so sweet a place.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "I weep for Adonais — he is dead! O, weep for Adonais! though our tears Thaw not the frost which binds so dear a head!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Till the Future dares Forget the Past, his fate and fame shall be An echo and a light unto eternity!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Most musical of mourners, weep again!", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "He died, Who was the Sire of an immortal strain, Blind, old, and lonely.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "To that high Capital, where kingly Death Keeps his pale court in beauty and decay, He came.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "The quick Dreams, The passion-winged Ministers of thought.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "Lost Angel of a ruined Paradise! She knew not 'twas her own; as with no stain She faded, like a cloud which had outwept its rain.", Author = "Percy Bysshe Shelley" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Percy_Bysshe_Shelley", Text = "And others came... Desires and Adorations, Winged Persuasions and veiled Destinies, Splendours, and GloOms, and glimmering Incarnations", Author = "Percy Bysshe Shelley" },
        };
    }
}